                    hitY = sh.y + k.h - 1;
                    for (x = 0; x < k.w && !hurt; x++) {
                        mi = solidAt(G.mer, sh.x + x, hitY);
                        if (mi >= 0) { erode(G.mer[mi], sh.x + Math.floor(k.w / 2), hitY, k.r, 1, H.rand); sh.dead = true; hurt = true; }
                    }
