            if (G.feast) { G.feast.ms -= TICK; if (!H.reduced) { G.feast.y += 1; } if (G.feast.ms <= 0) { G.feast = null; } }
            if (G.popTxt) { G.popTxt.ms -= TICK; if (G.popTxt.ms <= 0) { H.fill(0, 2, 40, 1, ' ', false); G.popTxt = null; } }
