            saveBest();
            G.mode = 'CLEAR';
            G.ms = 0;
            G.shots = []; G.mys = null;
            draw();
            flash(G.wave >= WAVES ? 'HOLD! THE LAST FIGHTER FALLS!' : 'WAVE CLEAR. THE REEVE CALLS A BREAK.', 2000);
            sfx([[523, 70], [659, 70], [784, 70], [1047, 130]]);
