            if (G.won) {
                f = H.reduced ? 0 : Math.floor(G.ms / 300) % 2;
                if (f === G.of) { return; }
                G.of = f;
                G.sprites = [];
                spr('win', 0, 0); spr('arcV', 74, 59); spr('A1', 196, 62); spr('C2', 214, 62); spr('B1', 232, 62);
                spr(f ? 'flag2' : 'flag1', 109, 30);
                H.sprites(G.sprites);
                return;
            }
            f = H.reduced ? 2 : (G.ms < 500 ? 0 : (G.ms < 800 ? 1 : 2));
            if (f === G.of) { return; }
            if (f === 2 && G.of >= 0 && !H.reduced) { sfx([[110, 90]]); }
            G.of = f;
            G.sprites = [];
            spr('fallbg', 0, 0); spr('tarp' + f, 84, 23); spr('A1', 48, 62); spr('B2', 66, 62); spr('C1', 214, 62);
